package com.bank.authsec;

import java.util.*;
import java.util.logging.*;

public class BrokenAuthDemo {
    private static final Logger log = Logger.getLogger(BrokenAuthDemo.class.getName());
    static final String BANK_NAME = "National Bank of India";

    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new BankLogFormatter());
        ch.setLevel(Level.ALL);
        root.addHandler(ch);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        AuthService auth = new AuthService(5);

        // Correct password + correct MFA -> success.
        try {
            auth.login("rajesh", "Str0ng!Passphrase", "123456");
            log.info("Login success (password + MFA verified)");
        } catch (RuntimeException e) {
            log.severe("Unexpected: " + e.getMessage());
        }

        // Correct password but NO/invalid MFA -> refused.
        try {
            auth.login("rajesh", "Str0ng!Passphrase", "000000");
        } catch (MfaRequiredException e) {
            log.warning("Refused: " + e.getMessage());
        }

        // Brute force: repeated wrong passwords trigger lockout.
        for (int i = 1; i <= 6; i++) {
            try {
                auth.login("rajesh", "wrong" + i, "123456");
            } catch (AccountLockedException e) {
                log.severe("Attempt " + i + ": " + e.getMessage());
            } catch (RuntimeException e) {
                log.warning("Attempt " + i + ": " + e.getMessage());
            }
        }
    }
}

