class UserCredential {
    final String username; final String passwordHash; final String mfaSecret;
    int failedAttempts; boolean locked;
    UserCredential(String u, String h, String m) { username = u; passwordHash = h; mfaSecret = m; }
}

// ─── Would be in AccountLockedException.java ───
class AccountLockedException extends RuntimeException {
    AccountLockedException(String m) { super(m); }
}

// ─── Would be in MfaRequiredException.java ───
class MfaRequiredException extends RuntimeException {
    MfaRequiredException(String m) { super(m); }
}

// ─── Would be in AuthService.java ───
class AuthService {
    private final int maxAttempts;
    private final UserCredential rajesh =
        new UserCredential("rajesh", "bcrypt(Str0ng!Passphrase)", "JBSWY3DPEHPK3PXP");
    AuthService(int maxAttempts) { this.maxAttempts = maxAttempts; }

    void login(String username, String rawPassword, String totp) {
        UserCredential u = rajesh; // lookup by username in production
        if (u.locked) throw new AccountLockedException("account locked after too many attempts");

        // 1. Verify password against the slow hash (simulated bcrypt match).
        if (!u.passwordHash.equals("bcrypt(" + rawPassword + ")")) {
            u.failedAttempts++;
            if (u.failedAttempts >= maxAttempts) {
                u.locked = true;
                throw new AccountLockedException("too many failures -> account locked");
            }
            throw new RuntimeException("invalid credentials"); // generic, no enumeration
        }
        u.failedAttempts = 0; // reset on success

        // 2. Require a valid MFA code (simulated TOTP check).
        if (!"123456".equals(totp))
            throw new MfaRequiredException("valid MFA code required");
    }
}

